CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations(name text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,description text,treat_as_actor boolean NOT NULL DEFAULT true,treat_as_source boolean NOT NULL DEFAULT true,aliases text[] NOT NULL DEFAULT '{}',category text,belongs_to text,dominance_level text,dominance_districts text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feeds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE,platform text NOT NULL CHECK(platform IN('instagram','facebook','x','youtube')),url text NOT NULL,url_verification_status text NOT NULL DEFAULT 'pending' CHECK(url_verification_status IN('pending','pending_retry','completed','failed')),is_active boolean NOT NULL DEFAULT true,failed_reason text,name text,username text,about text,external_id text,profile_picture text,followers_count bigint,content_count bigint NOT NULL DEFAULT 0,follows_count bigint,is_verified_account boolean,retry_count integer NOT NULL DEFAULT 0,retry_started_at timestamptz,last_updated_at timestamptz,profile_raw jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,platform));
CREATE INDEX feeds_external_id_platform_idx ON feeds(external_id,platform);

CREATE TABLE scrape_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE,status text NOT NULL CHECK(status IN('queued','running','completed','partially_completed','failed','cancelled')),request jsonb NOT NULL,callback_url text,progress jsonb NOT NULL DEFAULT '{}',error text,cancel_requested boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,completed_at timestamptz,expires_at timestamptz NOT NULL);
CREATE TABLE job_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE,feed_id uuid NOT NULL REFERENCES feeds(id) ON DELETE CASCADE,input_url text NOT NULL,platform text NOT NULL CHECK(platform IN('instagram','facebook','x','youtube')),status text NOT NULL DEFAULT 'queued',pending_tasks integer NOT NULL DEFAULT 0,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,feed_id));

CREATE TABLE contents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,target_id uuid NOT NULL REFERENCES job_targets(id) ON DELETE CASCADE,source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE,feed_id uuid NOT NULL REFERENCES feeds(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending',platform text NOT NULL,type text NOT NULL CHECK(type IN('textual','video','image','carousel')),external_id text NOT NULL,published_at timestamptz NOT NULL,url text NOT NULL,thumbnail_url text,hashtags text[] NOT NULL DEFAULT '{}',raw_title text,raw_description text,title text,description text,transcript text,raw_image_ocr_text text,image_ocr_text text,summary text,duration_seconds numeric,likes_count bigint,comments_count bigint,shares_count bigint,views_count bigint,engagement_rate real,sentiment text,categories text[] NOT NULL DEFAULT '{}',district text,language text,is_political boolean,is_governance boolean,stance text,actors jsonb NOT NULL DEFAULT '[]',claim text,is_seeded boolean NOT NULL DEFAULT false,reasoning text,conversation_id text,provider_raw jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,feed_id,external_id,platform));
CREATE INDEX contents_feed_id_idx ON contents(feed_id);
CREATE INDEX contents_published_at_idx ON contents(published_at DESC);
CREATE INDEX contents_status_published_idx ON contents(status,published_at DESC);
CREATE INDEX contents_hashtags_gin_idx ON contents USING gin(hashtags);

CREATE TABLE content_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,content_id uuid NOT NULL REFERENCES contents(id) ON DELETE CASCADE,platform text NOT NULL,external_id text NOT NULL,text text NOT NULL,likes_count bigint NOT NULL DEFAULT 0,replies_count bigint NOT NULL DEFAULT 0,owner_external_id text,owner_name text,owner_username text,owner_profile_picture text,timestamp timestamptz NOT NULL,provider_raw jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,platform,external_id));
CREATE INDEX content_comments_content_id_idx ON content_comments(content_id);
CREATE TABLE media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,content_id uuid NOT NULL REFERENCES contents(id) ON DELETE CASCADE,media_type text NOT NULL,original_url text NOT NULL,durable_url text,storage_key text,mime_type text,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(content_id,original_url));
CREATE TABLE enrichment_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,content_id uuid NOT NULL REFERENCES contents(id) ON DELETE CASCADE,media_id uuid REFERENCES media(id) ON DELETE SET NULL,kind text NOT NULL CHECK(kind IN('caption','video_precheck','transcription','ocr')),status text NOT NULL,text text,data jsonb,external_request_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(content_id,kind));

CREATE TABLE provider_attempts(id bigserial PRIMARY KEY,job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,target_id uuid REFERENCES job_targets(id) ON DELETE CASCADE,provider text NOT NULL,capability text NOT NULL,status text NOT NULL,duration_ms integer,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES scrape_jobs(id) ON DELETE CASCADE,url text NOT NULL,status text NOT NULL,attempts integer NOT NULL DEFAULT 0,response_status integer,error text,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_receipts(request_id text PRIMARY KEY,service text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX scrape_jobs_status_idx ON scrape_jobs(status);
CREATE INDEX scrape_jobs_expiry_idx ON scrape_jobs(expires_at);
